static const qnob_info_glyph_dsc_t* lv_font_montserrat_64_info_find(uint32_t letter) {
    for (uint32_t i = 0; i < sizeof(lv_font_montserrat_64_info_glyphs) / sizeof(lv_font_montserrat_64_info_glyphs[0]); ++i) {
        if (lv_font_montserrat_64_info_glyphs[i].unicode == letter) return &lv_font_montserrat_64_info_glyphs[i];
    }
    return NULL;
}

static bool lv_font_montserrat_64_info_get_glyph_dsc(const lv_font_t* font, lv_font_glyph_dsc_t* dsc_out, uint32_t letter, uint32_t letter_next) {
    (void)font;
    (void)letter_next;
    const qnob_info_glyph_dsc_t* g = lv_font_montserrat_64_info_find(letter);
    if (g == NULL) return false;
    dsc_out->adv_w = g->adv_w;
    dsc_out->box_w = g->box_w;
    dsc_out->box_h = g->box_h;
    dsc_out->ofs_x = g->ofs_x;
    dsc_out->ofs_y = g->ofs_y;
    dsc_out->bpp = 4;
    dsc_out->is_placeholder = 0;
    return true;
}

static const uint8_t* lv_font_montserrat_64_info_get_glyph_bitmap(const lv_font_t* font, uint32_t letter) {
    (void)font;
    const qnob_info_glyph_dsc_t* g = lv_font_montserrat_64_info_find(letter);
    if (g == NULL || g->box_w == 0 || g->box_h == 0) return NULL;
    return &lv_font_montserrat_64_info_bitmap[g->bitmap_index];
}

